part of 'user_screens.dart';

class ExpiryProductsScreen extends StatelessWidget { const ExpiryProductsScreen(this.state, {super.key}); final UserState state;
  @override Widget build(BuildContext context) { final limit = switch (state.expiryFilter) {'Expired' => -1, '7 Days' => 7, '30 Days' => 30, _ => 90}; final today = DateTime.now(); final rows = state.batches.where((b) { final date = DateTime.tryParse('${b['expiry_date']}'); if (date == null) return false; final days = date.difference(DateTime(today.year, today.month, today.day)).inDays; return limit == -1 ? days < 0 : days >= 0 && days <= limit; }).toList(); return UserShell(state: state, title: 'Expiry Products', showBack: true, child: Column(children: [
    SizedBox(height: 50, child: ListView(scrollDirection: Axis.horizontal, padding: const EdgeInsets.all(6), children: [for (final f in ['Expired', '7 Days', '30 Days', '90 Days']) Padding(padding: const EdgeInsets.symmetric(horizontal: 3), child: ChoiceChip(label: Text(f), selected: state.expiryFilter == f, onSelected: (_) => state.setExpiryFilter(f)))])),
    Expanded(child: rows.isEmpty ? const EmptyMessage('No batches match this expiry window.') : ListView.builder(padding: const EdgeInsets.all(12), itemCount: rows.length, itemBuilder: (_, i) { final b = rows[i]; final date = DateTime.parse('${b['expiry_date']}'); final days = date.difference(DateTime(today.year, today.month, today.day)).inDays; return UserCard(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [Expanded(child: Text('Product #${b['item']}', style: const TextStyle(fontWeight: FontWeight.w800))), StatusPill(days < 0 ? 'Expired' : '$days days')]), Text('Batch ${b['batch_number']}  •  Quantity ${number(b['quantity'])}'), Text('Expiry: ${date.day}/${date.month}/${date.year}'), Wrap(spacing: 5, children: ['Remove from Shelf', 'Clearance', 'Return', 'Dispose'].map((a) => TextButton(onPressed: () => _notice(context, '$a action must be confirmed in inventory management.'), child: Text(a, style: const TextStyle(fontSize: 11)))).toList())])); }))
  ])); }
}
